using System;
using System.IO;
using System.Threading;
using UnityEditor;
using UnityEngine;
using VenusWorld;
namespace Planetary.EditorTools {
public static class TunnelLightingValidation {
 static void Require(bool ok,string text){if(!ok)throw new Exception(text);}
 public static void Settle(PlanetFlight flight){var time=System.Diagnostics.Stopwatch.StartNew();while(time.Elapsed.TotalSeconds<120){flight.Excavation.Tick();if(flight.Excavation.Volume.AllSettled){Physics.SyncTransforms();return;}Thread.Sleep(1);}throw new Exception("Long-distance volume/lighting did not settle");}
 static float CentrePixel(Camera cam){var rt=new RenderTexture(128,128,24);var tex=new Texture2D(128,128,TextureFormat.RGB24,false);var old=cam.targetTexture;var active=RenderTexture.active;cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;tex.ReadPixels(new Rect(0,0,128,128),0,0);tex.Apply();var c=tex.GetPixel(64,64);cam.targetTexture=old;RenderTexture.active=active;UnityEngine.Object.DestroyImmediate(tex);rt.Release();UnityEngine.Object.DestroyImmediate(rt);return c.grayscale;}
 static PlanetFlight live;static double started;static string report;
 public static void StartLive(){live=UnityEngine.Object.FindFirstObjectByType<PlanetFlight>();Require(Application.isPlaying&&live,"Play the planet scene first");live.Initialize();var direction=VenusData.Direction(-7.5,303);var observer=direction*(live.Sampler.SurfaceRadius(direction)-140);Require(live.Excavation.Store.Sample(observer)>.8,"Existing 140 m verification shaft is not open");live.VerificationInputLock=true;live.StopCruise();live.SetPositionForVerification(observer);live.View.transform.rotation=Quaternion.LookRotation(direction.Float,Vector3.up);live.SetHeadlamp(false);started=EditorApplication.timeSinceStartup;report=Path.Combine(Application.dataPath,"../Documentation/tunnel-lighting-live.txt");EditorApplication.update-=LiveTick;EditorApplication.update+=LiveTick;}
 static void LiveTick(){if(!live||!Application.isPlaying){EditorApplication.update-=LiveTick;return;}try{Require(EditorApplication.timeSinceStartup-started<120,"Live lighting did not settle");if(!live.Excavation.Volume.AllSettled)return;float open=CentrePixel(live.View);Require(open>.08,"Existing shaft shows the sky with lamp off");Excavation.EditorTools.TerrainBridge.Capture();File.Copy(Path.Combine(Application.dataPath,"../Library/TerrainBridge/preview.png"),Path.Combine(Application.dataPath,"../Documentation/tunnel-live-sky.png"),true);live.SetHeadlamp(true);live.VerificationInputLock=false;EditorApplication.update-=LiveTick;File.WriteAllText(report,$"PASS: existing saved 140 m shaft, sky visible with lamp off; centre luminance {open:F4}; {live.Excavation.Volume.VisibleCount} visible chunks. Headlamp enabled and control released.\n");Debug.Log("LIVE TUNNEL LIGHTING VALIDATION PASSED");}catch(Exception ex){live.SetHeadlamp(true);live.VerificationInputLock=false;EditorApplication.update-=LiveTick;File.WriteAllText(report,"FAIL: "+ex);Debug.LogException(ex);}}
 static Color[] Pixels(Camera camera){var rt=new RenderTexture(256,256,24);var tex=new Texture2D(256,256,TextureFormat.RGB24,false);var old=camera.targetTexture;var active=RenderTexture.active;camera.targetTexture=rt;camera.Render();RenderTexture.active=rt;tex.ReadPixels(new Rect(0,0,256,256),0,0);tex.Apply();var pixels=tex.GetPixels();camera.targetTexture=old;RenderTexture.active=active;UnityEngine.Object.DestroyImmediate(tex);rt.Release();UnityEngine.Object.DestroyImmediate(rt);return pixels;}
 public static void Regressions(){BatchVerify();PlanetVolumeValidation.BatchVerify();PlanetFlightSetup.BatchVerify();}
 public static void BatchVerify(){
  Unity.Collections.NativeLeakDetection.Mode=Unity.Collections.NativeLeakDetectionMode.EnabledWithStackTrace;
  PlanetFlightSetup.Create();var flight=UnityEngine.Object.FindFirstObjectByType<PlanetFlight>();flight.planet=UnityEngine.Object.Instantiate(flight.planet);flight.planet.name="LightingTest"+Guid.NewGuid().ToString("N");flight.Initialize();Require(!ShaderUtil.ShaderHasError(Shader.Find("Planetary/Surface")),"Lighting shader compilation");
  var direction=VenusData.Direction(-7.5,303);double surface=flight.Sampler.SurfaceRadius(direction);var mouth=direction*surface;var observer=direction*(surface-140);var store=flight.Excavation.Store;for(double depth=-8;depth<=146;depth+=2)store.Sculpt(direction*(surface-depth),3,false);store.Save();flight.SetPositionForVerification(observer);flight.View.transform.rotation=Quaternion.LookRotation(direction.Float,Vector3.up);flight.SetHeadlamp(false);Settle(flight);
  Require(flight.Excavation.Volume.IsVisible(VolumeKey.At(mouth)),"Tunnel mouth still rendered 140 metres away");Require(flight.Excavation.Volume.IsVisible(VolumeKey.At(direction*(surface-70))),"Intermediate walls retained beyond old cutoff");var view=store.ReadView(observer,8192);Require(view.Sky(observer,direction,4096,out _),"Sky visible through open shaft");float open=CentrePixel(flight.View);Require(open>.08,"Sky renders through deep shaft instead of forced black");string folder=Path.Combine(Application.dataPath,"../Library/TerrainBridge");Excavation.EditorTools.TerrainBridge.Capture();File.Copy(Path.Combine(folder,"preview.png"),Path.Combine(folder,"tunnel-open-sky.png"),true);
  store.Sculpt(direction*(surface-40),5,true);Settle(flight);view=store.ReadView(observer,8192);Require(!view.Sky(observer,direction,4096,out _),"Rock plug blocks skylight");float closed=CentrePixel(flight.View);Require(closed<open*.5f,"Plug visibly blocks the entrance");Excavation.EditorTools.TerrainBridge.Capture();File.Copy(Path.Combine(folder,"preview.png"),Path.Combine(folder,"tunnel-sealed.png"),true);store.Undo();Settle(flight);Require(store.ReadView(observer,8192).Sky(observer,direction,4096,out _),"Undo restores skylight");
  var farPoint=observer-direction*1000;Require(store.Sculpt(farPoint,3,false)>0,"One kilometre test cavity excavates solid rock");Settle(flight);Require(flight.Excavation.Volume.IsVisible(VolumeKey.At(farPoint)),"Edited cavity retained at one kilometre");store.Undo();Settle(flight);
  // Check actual indirect transport on a cave wall, and reject light through a solid wall.
  var probe=observer;var tangent=Vector3.ProjectOnPlane(Vector3.up,direction.Float).normalized;var towardWall=new DVector(tangent.x,tangent.y,tangent.z);var field=store.ReadView(observer,8192);var bounce=VoxelLighting.LampBounce(field,probe,probe,tangent,5);Require(bounce.r>.0001,"Lamp produces nonzero bounced irradiance");var solid=probe+towardWall*8;Require(VoxelLighting.LampBounce(field,solid,probe,tangent,5).r==0,"Solid probes reject light leaks");Require(!field.Clear(probe,solid),"Rock occludes direct light rays");
  flight.View.transform.rotation=Quaternion.LookRotation(-direction.Float,Vector3.up);flight.SetHeadlamp(true);for(int i=0;i<120;i++){flight.Excavation.Tick();Thread.Sleep(5);}Excavation.EditorTools.TerrainBridge.Capture();File.Copy(Path.Combine(folder,"preview.png"),Path.Combine(folder,"tunnel-shadowed-lamp.png"),true);Require(!ShaderUtil.ShaderHasError(Shader.Find("Planetary/Surface")),"All used shadow/light variants compile");
  Light lamp=null;foreach(var light in UnityEngine.Object.FindObjectsByType<Light>(FindObjectsSortMode.None))if(light.name=="Shadowed headlamp")lamp=light;Require(lamp,"Real spotlight exists");lamp.transform.localPosition=new Vector3(2.2f,.1f,0);lamp.transform.localRotation=Quaternion.LookRotation(new Vector3(-2.2f,0,9));lamp.intensity=12;var right=flight.View.transform.right;var forward=flight.View.transform.forward;var pillar=observer+new DVector(forward.x,forward.y,forward.z)*3+new DVector(right.x,right.y,right.z)*1.6;store.Sculpt(pillar,1,true);Settle(flight);lamp.shadows=LightShadows.Soft;var shadowed=Pixels(flight.View);lamp.shadows=LightShadows.None;var unshadowed=Pixels(flight.View);int shadowPixels=0;for(int i=0;i<shadowed.Length;i++)if(unshadowed[i].grayscale-shadowed[i].grayscale>.005)shadowPixels++;Require(shadowPixels>20,"Spotlight casts measurable shadows on edited rock: "+shadowPixels);lamp.shadows=LightShadows.Soft;
  File.WriteAllText(Path.Combine(folder,"tunnel-lighting-validation.txt"),$"PASS: 140 m entrance and connecting tunnel meshes retained; edited geometry retained at 1 km; visible sky with lamp off; fill plug blocks sky and image; undo restores opening; nonzero one-bounce lamp transport; solid probes/rock rays reject light; shadow shader variants compile.\nOpen centre luminance {open:F4}; sealed {closed:F4}; bounce {bounce.r:F6}; shadow-darkened pixels {shadowPixels}.\nView distance {flight.planet.excavationViewDistance} m; resident meshes {flight.Excavation.Volume.ResidentCount}; visible {flight.Excavation.Volume.VisibleCount}.\n");Debug.Log("TUNNEL VISIBILITY AND LIGHTING VALIDATION PASSED");flight.Excavation.DisposeResources();flight.Tiles.Dispose();UnityEngine.Object.DestroyImmediate(flight.gameObject);
 }
}
}
